xpath.script:
// Limpiar menús duplicados (Directorio, Inicio, Tienda)
(function() {
    function cleanDuplicateMenus() {
        // Rutas a limpiar (mantener solo la primera ocurrencia de cada una)
        var pathsToClean = ['/directorio', '/', '/shop'];

        ['#top_menu', '#top_menu_collapse_mobile'].forEach(function(selector) {
            var container = document.querySelector(selector);
            if (!container) return;

            pathsToClean.forEach(function(path) {
                var seen = false;
                container.querySelectorAll('a[href="' + path + '"]').forEach(function(link) {
                    var li = link.closest('li');
                    if (!li) return;
                    if (seen) {
                        li.style.display = 'none';
                    } else {
                        seen = true;
                    }
                });
            });
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', cleanDuplicateMenus);
    } else {
        cleanDuplicateMenus();
    }
    setTimeout(cleanDuplicateMenus, 500);
    setTimeout(cleanDuplicateMenus, 1000);
})();

document.addEventListener('DOMContentLoaded', function() {
    var productImages = document.querySelectorAll('.oe_product_image_img');
    productImages.forEach(function(img) {
        img.style.objectFit = 'cover';
        img.classList.remove('object-fit-contain');
        img.classList.add('object-fit-cover');
    });
});
